package app.brokenn.extension.jiohotstar.settings;

import android.content.Context;
import android.graphics.Typeface;

// Embedded fonts (base64) unpacked to the cache dir on first use.
public final class Fonts {
    private Fonts() {}

    // Intro Script Heavy (user-supplied TTF).
    private static final String[] INTRO_SCRIPT_B64 = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    };


    public static Typeface introScript(Context ctx) {
        return load(ctx, INTRO_SCRIPT_B64, "intro_script.ttf");
    }

    private static final java.util.HashMap<String, Typeface> CACHE =
        new java.util.HashMap<String, Typeface>();

    private static Typeface load(Context ctx, String[] chunks, String fileName) {
        synchronized (CACHE) {
            if (CACHE.containsKey(fileName)) return CACHE.get(fileName);
            Typeface loaded = null;
            try {
                StringBuilder b64 = new StringBuilder();
                for (String chunk : chunks) b64.append(chunk);
                byte[] bytes = android.util.Base64.decode(b64.toString(), android.util.Base64.DEFAULT);
                java.io.File file = new java.io.File(ctx.getCacheDir(), fileName);
                try (java.io.FileOutputStream out = new java.io.FileOutputStream(file)) {
                    out.write(bytes);
                }
                loaded = Typeface.createFromFile(file);
            } catch (Throwable t) {
                loaded = null;
            }
            CACHE.put(fileName, loaded);
            return loaded;
        }
    }
}
